
function art(m){let paths='';if(!m){for(let i=0;i<10;i++){let x=414+i*7.8,y=186+i*0.5;paths+=`<path d="M 305 353 C 390 353 ${x+7} 315 ${x} 260 C ${x-16} 173 ${x-11} ${75+i*9.6} ${518-i*.9} ${75+i*9.6} C ${573-i*4.9} ${75+i*9.6} ${603-i*8.7} ${117+i*7.5} ${603-i*8.7} 186 L ${603-i*8.7} 218 C ${603-i*8.7} ${285+i*10} ${652+i*4} ${239+i*11} ${680+i*4} ${206+i*11} C ${714+i*4} ${169+i*12} 727 ${166+i*13.4} 763 ${168+i*13.4}"/>`;}return `<svg class="art" viewBox="0 0 763 540"><g fill="none" stroke="#191a18" stroke-width="1.05">${paths}</g><circle cx="652" cy="138" r="37" fill="#ae5533"/><circle cx="625" cy="227" r="12.5" fill="#21211f"/></svg>`;}for(let i=0;i<8;i++)paths+=`<path d="M ${159+i*7} 39 C ${160+i*7} 88 ${184+i*7} 114 ${210+i*7} 143 M ${68+i*7} 235 C ${89+i*6} ${166+i*8} ${127+i*3} ${183+i*7} ${151+i*3} ${199+i*7} C 176 ${218+i*6} 198 ${210+i*8} 211 ${193+i*8}"/>`;return `<svg class="art" viewBox="0 0 203 255"><g fill="none" stroke="#22221e" stroke-width="1">${paths}</g><circle cx="178" cy="172" r="25" fill="#ac5130"/></svg>`;}
function thread(m){return m?`<svg class="thread" viewBox="0 0 203 1404"><path d="M -1 161 C -1 192 24 202 24 238 L 24 1300 Q 26 1340 19 1366" fill="none" stroke="#b34822" stroke-width="1.35"/><g fill="#faf7ef" stroke="#b34822" stroke-width="2.4">${[264,654,964].map(y=>`<circle cx="24" cy="${y}" r="6.8"/>`).join('')}</g><circle cx="19" cy="1366" r="5.5" fill="#b34822"/></svg>`:`<svg class="thread" viewBox="0 0 763 1404"><path d="M 481.718 280.542 C 466.050 321.892 388.005 349.869 317 353 C 245 351 193 392 192 463 C 189 554 271 642 229 705 C 202 746 186 772 185 822 C 180 894 224 918 228 971 C 233 1010 199 1053 199 1076 C 193 1134 268 1226 195 1333" fill="none" stroke="#b44822" stroke-width="1.6"/><g fill="#fcf9f1" stroke="#b44822" stroke-width="2.6">${[[192,463],[193,767],[199,1076]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="9"/>`).join('')}</g><circle cx="195" cy="1333" r="6.3" fill="#ac4825"/></svg>`;}

// Local fixtures only. No network requests or production API integration.
const samples=HWPrototype.tasks.map(t=>({...t,category:t.category||'Uncategorized'}));
const params=new URLSearchParams(location.search);
const state={category:'All categories',limit:3,gap:'loading',kind:'loading',list:'loading',more:'idle',failedMore:false,listGeneration:0,scroll:0,opener:null};
const categories=[...new Set(samples.map(t=>t.category))];
state.category=categories.includes(params.get('category'))?params.get('category'):'All categories';state.limit=Math.max(3,Math.min(samples.length,Math.floor(Number(params.get('shown'))||3)));
const validStates=['ready','missing','zero','empty','error','loading'];
function requested(part){const v=params.get(part+'State')||params.get('previewState')||'ready';return validStates.includes(v)?v:'ready'}
const value=v=>v===null?'<span aria-label="Data unavailable">—</span>':String(v);
const conclusions=['human','undetermined','agent','undetermined','human','undetermined','agent','undetermined'];
const count=rows=>[rows.length,...['human','undetermined','agent'].map(k=>rows.filter(t=>conclusions[samples.indexOf(t)]===k).length)];
const values=Object.fromEntries(categories.map(c=>[c,count(samples.filter(t=>t.category===c))]));
function status(part){const v=state[part];if(v==='loading')return '<p class="status" role="status">Loading…</p>';if(v==='error')return `<div class="status" role="status">Could not load this section. <button data-retry="${part}">Try again</button></div>`;return ''}
function gap(){let msg=status('gap');if(msg)return msg;const missing=state.gap==='missing',zero=['zero','empty'].includes(state.gap);let nums=missing?[null,null,null]:zero?[0,0,0]:count(samples).slice(1);return `<p class="total">Published tasks <strong>${value(missing?null:zero?0:samples.length)}</strong></p><div class="metrics">${['Human leading','Undetermined','Agent leading'].map((label,i)=>`<div class="metric"><div class="dash">${value(nums[i])}</div><span>${label}</span></div>`).join('')}</div><p class="metric-note">Task counts, not votes or ability scores.<br>${missing?'Data unavailable.':zero?'No published tasks in this preview.':'Simulated snapshot; not live data.'}</p>`}
function kind(){let msg=status('kind');if(msg)return msg;return `<div class="table-scroll" tabindex="0" aria-label="Conclusion distribution by category"><table><thead><tr>${['Category','Published tasks','Human leading','Undetermined','Agent leading'].map(t=>`<th scope="col">${t}</th>`).join('')}</tr></thead><tbody>${categories.map(c=>`<tr><th scope="row"><button class="text-link" data-category="${c}">${c}</button></th>${values[c].map(v=>`<td>${value(state.kind==='missing'?null:['zero','empty'].includes(state.kind)?0:v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="table-note">Select a category to filter Most Discussed only.<br>0 = no tasks · — = unavailable data.</p>`}
function filtered(){return samples.filter(t=>state.category==='All categories'||t.category===state.category)}
function listing(){let msg=status('list');const items=filtered(),empty=['empty','zero'].includes(state.list);return `<label class="sr-only" for="FILTER">Filter Most Discussed</label><select id="FILTER" class="filter" aria-label="Filter Most Discussed">${['All categories',...categories].map(c=>`<option ${c===state.category?'selected':''}>${c}</option>`).join('')}</select><p class="filter-feedback" role="status">${state.category} · ${state.list==='ready'?`Showing ${Math.min(state.limit,items.length)} of ${items.length} example tasks`:empty?'No tasks':''}</p>${msg|| (state.list==='missing'?'<p class="status">Discussion data unavailable.</p>':empty?'<p class="status">No discussed tasks in this category.</p>':items.slice(0,state.limit).map(t=>`<article class="task"><div class="task-title">${t.title}<button class="category text-link" data-category="${t.category}">${t.category}</button></div><p class="summary">${t.summary}</p><a href="${detailURL(t.id)}" class="view" data-detail="${t.id}">View task <span>↗</span></a></article>`).join(''))}${state.list==='ready'?(state.limit<items.length?`<button class="load" data-more ${state.more==='loading'?'disabled':''}>${state.more==='loading'?'Loading…':state.more==='error'?'Try loading more again':'Load more'}</button>${state.more==='error'?'<p class="status" role="status">Could not load more. Existing tasks are still available.</p>':''}`:'<p class="end" role="status" tabindex="-1">All example tasks shown.</p>'):''}`}
const boards=[];
for(const mobile of [false]){const b=document.createElement('div');b.className='board'+(mobile?' mobile':'');const key=mobile?'m':'d';b.innerHTML=art(mobile)+`<div class="hero"><h1>Where do<br>perspectives diverge?</h1><p>Explore how conclusions differ across published tasks, and discover what people are discussing.</p></div><section class="section s1" data-section-name="gap" aria-labelledby="${key}-gap"><div class="intro"><h2 class="label" tabindex="-1" id="${key}-gap">The Gap</h2><div class="shortline"></div><p class="description">How conclusions are distributed across all published tasks.</p></div><div class="gap-body" data-region="gap" aria-live="polite"></div></section><section class="section s2" data-section-name="kind" aria-labelledby="${key}-kind"><div class="intro"><h2 class="label" tabindex="-1" id="${key}-kind">By Kind</h2><div class="shortline"></div><p class="description">Compare conclusion distributions by task category.</p></div><div class="tablewrap" data-region="kind" aria-live="polite"></div></section><section class="section s3" data-section-name="list" aria-labelledby="${key}-list"><div class="intro"><h2 class="label" tabindex="-1" id="${key}-list">Most Discussed</h2><div class="shortline"></div><p class="description">Explore the most active task discussions from the last 7 days.</p><p class="muted counts">Based on unique commenting accounts and approved submissions. Discussion order is not a quality ranking.</p></div><div class="tasks" data-region="list" aria-live="polite"></div></section>`+thread(mobile);b.querySelectorAll('svg').forEach(svg=>svg.setAttribute('aria-hidden','true'));b.querySelector('.thread').setAttribute('preserveAspectRatio','none');document.querySelector('#boards').appendChild(b);boards.push(b)}
function resize(){const b=boards[0],w=b.clientWidth,h=b.offsetHeight,narrow=matchMedia('(max-width:759px)').matches,gutter=narrow?23:w*.255;const svg=b.querySelector('.thread');
// Preserve the approved SVG geometry and uniform scale; never rebuild its curves from section heights.
if(!narrow){svg.setAttribute('viewBox','0 0 763 1404');svg.style.height=(w*1404/763)+'px';svg.querySelector('path').setAttribute('d',"M 481.718 280.542 C 466.050 321.892 388.005 349.869 317 353 C 245 351 193 392 192 463 C 189 554 271 642 229 705 C 202 746 186 772 185 822 C 180 894 224 918 228 971 C 233 1010 199 1053 199 1076 C 193 1134 268 1226 195 1333");svg.querySelectorAll('g circle').forEach((c,i)=>{const [x,y]=[[192,463],[193,767],[199,1076]][i];c.setAttribute('cx',x);c.setAttribute('cy',y)});const end=svg.querySelector(':scope > circle');end.setAttribute('cx',195);end.setAttribute('cy',1333);scheduleDraw();return;}
svg.style.height='100%';svg.setAttribute('viewBox','0 0 '+w+' '+h);const ys=[...b.querySelectorAll('.section')].map(s=>s.offsetTop+48);let d=narrow?'M 23 270':'M '+(481.718*w/763)+' '+(280.542*w/763)+' C '+(466*w/763)+' '+(322*w/763)+' '+(388*w/763)+' '+(350*w/763)+' '+(317*w/763)+' '+(353*w/763);let prev=narrow?270:353*w/763;ys.forEach((y,i)=>{d+=' C '+(gutter-30)+' '+(prev+40)+' '+(gutter+30)+' '+(y-55)+' '+gutter+' '+y;prev=y});d+=' C '+(gutter-30)+' '+(prev+80)+' '+(gutter+45)+' '+(h-65)+' '+gutter+' '+(h-25);svg.querySelector('path').setAttribute('d',d);svg.querySelectorAll('g circle').forEach((c,i)=>{c.setAttribute('cx',gutter);c.setAttribute('cy',ys[i])});const end=svg.querySelector(':scope > circle');end.setAttribute('cx',gutter);end.setAttribute('cy',h-25);scheduleDraw();}
function render(part){boards.forEach((b,i)=>{const r=b.querySelector(`[data-region="${part}"]`);r.innerHTML=({gap,kind,list:listing})[part]().replaceAll('FILTER',`filter-${i}`);r.setAttribute('aria-busy',String(state[part]==='loading'||(part==='list'&&state.more==='loading')));});resize()}
requestAnimationFrame(()=>{for(const part of ['gap','kind','list']){state[part]=requested(part);render(part)}restorePosition();});
function selectCategory(c,b){state.listGeneration++;state.category=c;state.limit=3;state.more='idle';syncURL();render('list');b.querySelector('.s3').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});b.querySelector('.filter').focus({preventScroll:true})}
document.addEventListener('change',e=>{if(e.target.matches('.filter'))selectCategory(e.target.value,e.target.closest('.board'))});
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;const b=el.closest('.board');if(el.dataset.category)selectCategory(el.dataset.category,b);
if(el.dataset.retry){const part=el.dataset.retry;state[part]='loading';render(part);setTimeout(()=>{state[part]='ready';render(part)},300)}
if(el.hasAttribute('data-more')&&state.more!=='loading'){const generation=state.listGeneration;state.more='loading';render('list');setTimeout(()=>{if(generation!==state.listGeneration)return;if(params.has('moreError')&&!state.failedMore){state.failedMore=true;state.more='error'}else{state.limit+=3;state.more='idle';syncURL()}render('list');(b.querySelector('[data-more]')||b.querySelector('.end'))?.focus({preventScroll:true})},350)}
if(el.dataset.detail){state.scroll=scrollY;state.opener=el;savePosition();}
});
addEventListener('resize',resize);
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
// Reveal at the viewport boundary; keep content accessible with reduced motion.
const sections=[...document.querySelectorAll('.section')];
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:0,rootMargin:'0px 0px -12% 0px'});
sections.forEach(section=>{section.classList.add('reveal-ready');if(reduce.matches)section.classList.add('visible');else observer.observe(section)});
// Draw the existing path with scrolling. Geometry and the repaired join stay untouched.
const pathProgress=new WeakMap();let drawFrame=0;
function drawPaths(){drawFrame=0;boards.forEach(board=>{if(!board.getClientRects().length)return;const path=board.querySelector('.thread>path'),matrix=path.getScreenCTM();if(!matrix)return;const length=path.getTotalLength();let progress=1;
if(!reduce.matches){const edge=innerHeight*.84;let low=0,high=length;for(let i=0;i<18;i++){const mid=(low+high)/2,p=path.getPointAtLength(mid),y=matrix.b*p.x+matrix.d*p.y+matrix.f;if(y<edge)low=mid;else high=mid}progress=Math.max(pathProgress.get(path)||0,low/length);pathProgress.set(path,progress)}
path.style.strokeDasharray=`${length} ${length}`;path.style.strokeDashoffset=String(length*(1-progress));
board.querySelectorAll('.thread circle').forEach(circle=>{const y=matrix.b*Number(circle.getAttribute('cx'))+matrix.d*Number(circle.getAttribute('cy'))+matrix.f;if(reduce.matches||y<innerHeight*.84||progress>.999)circle.style.opacity='1';else if(circle.style.opacity!=='1')circle.style.opacity='0'});
});}
function scheduleDraw(){if(!drawFrame)drawFrame=requestAnimationFrame(drawPaths)}
addEventListener('scroll',scheduleDraw,{passive:true});addEventListener('resize',scheduleDraw);
new ResizeObserver(scheduleDraw).observe(document.querySelector('#boards'));
reduce.addEventListener('change',()=>{if(reduce.matches)sections.forEach(section=>section.classList.add('visible'));scheduleDraw()});scheduleDraw();

function syncURL(){const u=new URL(location.href);if(state.category==='All categories')u.searchParams.delete('category');else u.searchParams.set('category',state.category);u.searchParams.set('shown',state.limit);history.replaceState(history.state,'',u);}
function detailURL(id){const u=new URL('task-detail.html',location.href);u.searchParams.set('id',id);u.searchParams.set('return',location.pathname.split('/').pop()+location.search);return u.href;}
let restoring=true;const positionKey=()=> 'hw-board-position:'+location.pathname+location.search;
function savePosition(){if(restoring)return;try{sessionStorage.setItem(positionKey(),String(scrollY))}catch{}}
function restorePosition(){let y=0;try{y=Number(sessionStorage.getItem(positionKey()))||0}catch{}requestAnimationFrame(()=>{scrollTo(0,y);restoring=false;scheduleDraw()});}
addEventListener('pagehide',savePosition);addEventListener('scroll',savePosition,{passive:true});
const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);document.querySelector('.nav-links').classList.toggle('is-open',open)});document.querySelector('#account-button').onclick=()=>document.querySelector('#account-dialog').showModal();
